                    children: [],
                    getAttribute: (k) => attrs.get(k) ?? null,
                    setAttribute: (k, v) => attrs.set(k, v),
                    removeAttribute: (k) => attrs.delete(k),
                    appendChild: (child) => { child._parent = this; return child; },
                    textContent: '',
                    _attrs: attrs,
                };
            }
            const doc = {
                createElement: (tag) => makeEl(tag),
            };

            // renderSelectionOverlay
