            assert.strictEqual(mk.markValue(r2.marks.find((m) => mk.markType(m) === 'link')), 'https://second.com', 'href replaced');
            // remove by type
            fmt.applyMarkToBlockRange(blk, 6, 10, 'link', { mode: 'remove' });
