            assert.strictEqual(mod.findReferenceLineForOffset(null, 0), null);
            assert.strictEqual(mod.findReferenceLineForOffset({}, 0), null);
            assert.strictEqual(mod.findReferenceLineForOffset({ lines: [] }, 0), null);

